ALTER TABLE "storefront"."brand_asset" DROP CONSTRAINT "brand_asset_kind_check";--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" DROP CONSTRAINT "brand_asset_kind_content_type_check";--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" DROP CONSTRAINT "brand_asset_object_key_check";--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" DROP CONSTRAINT "brand_asset_dimensions_check";--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD COLUMN "seo_title" text;--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD COLUMN "seo_description" text;--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD COLUMN "social_image_alt" text;--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD COLUMN "social_image_asset_id" uuid;--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD CONSTRAINT "configuration_social_image_asset_id_brand_asset_id_fk" FOREIGN KEY ("social_image_asset_id") REFERENCES "storefront"."brand_asset"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_kind_check" CHECK ("storefront"."brand_asset"."kind" in ('logo', 'favicon', 'socialImage'));--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_kind_content_type_check" CHECK (("storefront"."brand_asset"."kind" = 'logo' and "storefront"."brand_asset"."content_type" = 'image/webp') or ("storefront"."brand_asset"."kind" = 'favicon' and "storefront"."brand_asset"."content_type" = 'image/png') or ("storefront"."brand_asset"."kind" = 'socialImage' and "storefront"."brand_asset"."content_type" = 'image/jpeg'));--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_object_key_check" CHECK ("storefront"."brand_asset"."object_key" ~ '^published/storefront/(logo|favicon|socialImage)/[0-9a-f-]{36}/[0-9a-f]{64}\.(webp|png|jpg)$');--> statement-breakpoint
ALTER TABLE "storefront"."brand_asset" ADD CONSTRAINT "brand_asset_dimensions_check" CHECK (("storefront"."brand_asset"."kind" = 'logo' and "storefront"."brand_asset"."width" between 1 and 1200 and "storefront"."brand_asset"."height" between 1 and 400) or ("storefront"."brand_asset"."kind" = 'favicon' and "storefront"."brand_asset"."width" = 64 and "storefront"."brand_asset"."height" = 64) or ("storefront"."brand_asset"."kind" = 'socialImage' and "storefront"."brand_asset"."width" = 1200 and "storefront"."brand_asset"."height" = 630));--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD CONSTRAINT "configuration_seo_title_check" CHECK ("storefront"."configuration"."seo_title" is null or ("storefront"."configuration"."seo_title" = btrim("storefront"."configuration"."seo_title") and length("storefront"."configuration"."seo_title") between 1 and 160));--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD CONSTRAINT "configuration_seo_description_check" CHECK ("storefront"."configuration"."seo_description" is null or ("storefront"."configuration"."seo_description" = btrim("storefront"."configuration"."seo_description") and length("storefront"."configuration"."seo_description") between 1 and 500));--> statement-breakpoint
ALTER TABLE "storefront"."configuration" ADD CONSTRAINT "configuration_social_image_alt_check" CHECK ("storefront"."configuration"."social_image_alt" is null or ("storefront"."configuration"."social_image_alt" = btrim("storefront"."configuration"."social_image_alt") and length("storefront"."configuration"."social_image_alt") between 1 and 250));